//! Parity gate: assert every Python-oracle case in `parity_fixture.txt`
//! produces the identical recorded token in Rust.
//!
//! The fixture is generated by `tests/parity_oracle.py`, which runs the real
//! `ledger.py` projection under the project venv. A failure here is a parity
//! failure, not a test bug; do not edit the fixture to go green — fix the
//! implementation and regenerate from the oracle.

use ezchain_replay::{
    assert_balanced, cash_account, fee_account, minor, position_account, realized_account,
    realized_pnl, replay_balances, replay_position, LedgerEntry, ReplayError, FUNDING_ACCOUNT,
    FUNDING_PREFIX,
};

const FIXTURE: &str = include_str!("parity_fixture.txt");

/// A held-out corpus (different `EZ_REPLAY_SEED`) can be checked without
/// overwriting the committed fixture.
fn fixture_text() -> String {
    match std::env::var("EZ_REPLAY_FIXTURE") {
        Ok(path) => std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("cannot read held-out fixture {path}: {err}")),
        Err(_) => FIXTURE.to_string(),
    }
}

fn err_token(error: &ReplayError, with_message: bool) -> String {
    if with_message {
        format!("E:{}:{}", error.code(), error.message())
    } else {
        format!("E:{}", error.code())
    }
}

fn decode_entry(encoded: &str) -> Result<LedgerEntry, ReplayError> {
    let fields: Vec<&str> = encoded.split('~').collect();
    assert_eq!(fields.len(), 5, "malformed entry in fixture: {encoded}");
    LedgerEntry::new(fields[0], fields[1], fields[2], fields[3], fields[4])
}

fn decode_tape(encoded: &str) -> Result<Vec<LedgerEntry>, ReplayError> {
    if encoded.is_empty() {
        return Ok(Vec::new());
    }
    encoded.split(';').map(decode_entry).collect()
}

fn run_case(op: &str, args: &[&str]) -> String {
    match op {
        "name" => {
            let account = match args[0] {
                "cash" => cash_account().to_string(),
                "fee" => fee_account().to_string(),
                "realized" => realized_account().to_string(),
                "funding" => FUNDING_ACCOUNT.to_string(),
                "prefix" => FUNDING_PREFIX.to_string(),
                "position" => position_account(args[1], args[2]),
                other => panic!("unknown name kind in fixture: {other}"),
            };
            format!("A:{account}")
        }
        "entry" => match decode_entry(args[0]) {
            Ok(_) => "OK".to_string(),
            Err(error) => err_token(&error, false),
        },
        "replay" => match decode_tape(args[0]) {
            Ok(entries) => match replay_balances(&entries) {
                Ok(balances) => {
                    let parts: Vec<String> = balances
                        .iter()
                        .map(|balance| {
                            format!(
                                "{}#{}#{}",
                                balance.account,
                                balance.amount.canonical(),
                                minor::signed_string(&balance.usd_minor)
                            )
                        })
                        .collect();
                    format!("R:{}", parts.join(";"))
                }
                Err(error) => err_token(&error, true),
            },
            Err(error) => err_token(&error, true),
        },
        "balance" => match decode_tape(args[0]) {
            Ok(entries) => match assert_balanced(&entries) {
                Ok(()) => "OK".to_string(),
                Err(error) => err_token(&error, true),
            },
            Err(error) => err_token(&error, true),
        },
        "pos" => match decode_tape(args[0]) {
            Ok(entries) => match replay_position(&entries) {
                Ok((quantity, cost)) => {
                    format!("P:{},{}", quantity.canonical(), cost.canonical())
                }
                Err(error) => err_token(&error, true),
            },
            Err(error) => err_token(&error, true),
        },
        "pnl" => match decode_tape(args[0]) {
            Ok(entries) => match realized_pnl(&entries) {
                Ok(value) => format!("V:{}", value.canonical()),
                Err(error) => err_token(&error, true),
            },
            Err(error) => err_token(&error, true),
        },
        other => panic!("unknown operation in fixture: {other}"),
    }
}

#[test]
fn python_oracle_parity() {
    let mut passed = 0usize;
    let mut failures: Vec<String> = Vec::new();
    let fixture = fixture_text();

    for (index, line) in fixture.lines().enumerate() {
        let fields: Vec<&str> = line.split('\t').collect();
        assert!(fields.len() >= 2, "malformed fixture line {}", index + 1);
        let op = fields[0];
        let expected = fields[fields.len() - 1];
        let actual = run_case(op, &fields[1..fields.len() - 1]);
        if actual == expected {
            passed += 1;
        } else {
            failures.push(format!(
                "line {} [{}]: expected {expected}, got {actual}",
                index + 1,
                op
            ));
        }
    }

    let total = fixture.lines().count();
    eprintln!("parity: {passed}/{total} cases match the Python oracle");
    if !failures.is_empty() {
        for failure in failures.iter().take(20) {
            eprintln!("  MISMATCH {failure}");
        }
        panic!("{} parity case(s) failed", failures.len());
    }
}
